final class ContextSignedWitnessReceiverMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean x,String text)throws Exception{return ContextSignedWitnessPlanMatrix.bind(x,text);}
 static ContextUniversalFrozenBranch.Limits limits(int rounds,int work){return new ContextUniversalFrozenBranch.Limits(rounds,16,16,512,256,work,65536,65536);}
 static ContextSignedWitnessFrameAudit.Receipt frame(Snapshot x,List<Snapshot> foreign){ContextSignedWitnessPlan.Result p=ContextSignedWitnessPlan.build(x,foreign,64,WORK);require(p.planned,p.reason);ContextSignedWitnessPlanAudit.Inspection a=ContextSignedWitnessPlanAudit.inspect(p.output,x,foreign,64,WORK);require(a.audited,a.reason);SignedSeedResult f=ContextWitnessResultTransport.signedWitnessFrame(a.output,x,foreign,64,8,WORK,WORK);require(f.assembled,f.reason);ContextSignedWitnessFrameAudit.Inspection checked=ContextSignedWitnessFrameAudit.inspect(f.output,a.output,x,foreign,64,8,WORK,WORK);require(checked.audited,checked.reason);return checked.output;}
 static ContextSignedWitnessReceiver.Result run(ContextSignedWitnessFrameAudit.Receipt f,boolean refuted){ContextUniversalFrozenBranch.Limits l=limits(16,WORK);ContextSignedWitnessReceiver.Result r=ContextSignedWitnessReceiver.run(f,64,l,WORK);require(r.status==(refuted?ContextSignedWitnessReceiver.Status.REFUTED:ContextSignedWitnessReceiver.Status.CHECKED),r.phase+": "+r.reason);ContextSignedWitnessReceiver.check(r,f,64,l,WORK);require(true,"fresh independent entire receiver replay, all Source/depth inventories");return r;}
 static void positive()throws Exception{
  Snapshot signed=bind(false,"!$u seed(u,1)&&~blocked(u,1);"),other=bind(false,"!foreignAnchor(1);");
  for(boolean grouped:new boolean[]{false,true})for(boolean reverse:new boolean[]{false,true})for(boolean clash:new boolean[]{false,true}){Snapshot x=bind(true,"!anchor(1); !@u seed(u,1)->"+(clash?"blocked":"~blocked")+"(u,1);");List<Snapshot> members=reverse?Arrays.asList(other,signed):Arrays.asList(signed,other);List<Snapshot> foreign=grouped?Collections.singletonList(ContextProductionNativeBinding.trusted("receiver",members,WORK)):members;ContextSignedWitnessFrameAudit.Receipt f=frame(x,foreign);ContextSignedWitnessReceiver.Result r=run(f,clash);require(r.checks.size()==foreign.size()+1,"all supplied cuts checked before result exposure");for(ContextUniversalFrozenConstraints.Result c:r.checks.values())require(c.closed&&c.input.signedSeeds==f&&c.common==f.frame.common,"closed kernel result bound exact signed row/frame scope");
   if(clash)require(r.checks.values().stream().flatMap(c->c.emptyProofs.stream()).anyMatch(p->p.support.sources.size()==2&&p.support.sources.stream().filter(s->s.localX).count()==1&&p.support.sources.contains(signed.primary.get(0).source)),"signed private negative atom actually refutes positive producer under exact bundle+rule Sources");else require(r.checks.values().stream().allMatch(c->c.emptyProofs.isEmpty()),"same negative sign is CHECKED, never silently flipped positive");require(!ContextUniversalNativeRows.inspect(x,grouped?foreign.get(0):signed,64,WORK).withinShape,"legacy classifier still rejects signed witness rows");
  }
  Snapshot x=bind(true,"!$u seed(u,1)&&~blocked(u,1);"),a=bind(false,"!@u seed(u,1)->blocked(u,1);");run(frame(x,Collections.singletonList(a)),true);require(true,"signed common witness literals also authenticated in self and foreign receivers");
  Snapshot root=bind(true,"!anchor(1); !@u seed(u,1)&&other(u,1)->blocked(u,1);"),separate=bind(false,"!$u other(u,1);");List<Snapshot> independent=Collections.singletonList(ContextProductionNativeBinding.trusted("different-origins",Arrays.asList(signed,separate),WORK));run(frame(root,independent),false);require(true,"same binder number in different Source never creates a witness join");Snapshot joint=bind(false,"!$u seed(u,1)&&other(u,1)&&~blocked(u,1);");run(frame(root,Collections.singletonList(joint)),true);require(true,"shared Source/binder control creates real signed contradiction");
  System.out.println("SIGNED_WITNESS_RECEIVER orders=8 signedPrivateAndCommon=true exactSources=true independentReplay=true originIdentity=true legacyClassifierUnchanged=true initialOnly=true");
 }
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static void incomplete(ContextSignedWitnessReceiver.Result r,String why){require(r.status==ContextSignedWitnessReceiver.Status.INCOMPLETE&&r.frame==null&&r.checks.isEmpty(),why+": no partial checks/refutation");}
 static void boundaries()throws Exception{
  Snapshot x=bind(true,"!anchor(1); !@u seed(u,1)->blocked(u,1);"),a=bind(false,"!$u seed(u,1)&&~blocked(u,1);"),bad=bind(false,"!@u p(u)||q(u);");for(boolean reverse:new boolean[]{false,true}){List<Snapshot> targets=reverse?Arrays.asList(bad,a):Arrays.asList(a,bad);ContextSignedWitnessFrameAudit.Receipt f=frame(x,targets);ContextSignedWitnessReceiver.Result r=ContextSignedWitnessReceiver.run(f,64,limits(16,WORK),WORK);incomplete(r,"later/earlier unsupported positive-head row blocks an otherwise real refutation");require(r.phase.equals("all-row-preflight"),"every row checked before any closure");}
  List<Snapshot> foreign=Collections.singletonList(a);ContextSignedWitnessFrameAudit.Receipt f=frame(x,foreign);incomplete(ContextSignedWitnessReceiver.run(f,1,limits(16,WORK),WORK),"whole per-receiver row bound");incomplete(ContextSignedWitnessReceiver.run(f,64,limits(16,1),WORK),"row/closure work bound");incomplete(ContextSignedWitnessReceiver.run(f,64,limits(16,WORK),1),"fresh frame audit work bound");incomplete(ContextSignedWitnessReceiver.run(f,64,limits(1,WORK),WORK),"ordinary receiver saturation limit cannot publish earlier completed checks");
  ContextUniversalNativeRows.Result rows=ContextUniversalNativeRows.inspectSigned(f,a,64,WORK,WORK);require(rows.classified&&rows.withinShape,"explicit signed row profile accepted with fresh frame receipt");PrivatePool pool=ContextWitnessResultTransport.scopedSignedPool(f,a,WORK);ContextUniversalFrozenConstraints.Result unsigned=ContextUniversalFrozenConstraints.close(rows,f.frame.common,pool,16,16,512,256,WORK);require(!unsigned.closed,"signed row profile cannot use old unsigned closure grammar");Snapshot alias=bind(false,"!$u seed(u,1)&&~blocked(u,1);");require(!ContextUniversalNativeRows.inspectSigned(f,alias,64,WORK,WORK).classified,"equal-text receiver is not expected actual cut");reject(()->ContextWitnessResultTransport.scopedSignedPool(f,alias,WORK),"scoped pool cannot rebind to another snapshot");
  Snapshot positive=bind(false,"!p(1);");ContextSignedWitnessFrameAudit.Receipt p=frame(x,Collections.singletonList(positive));PrivatePool signedPool=ContextWitnessResultTransport.scopedSignedPool(p,positive,WORK);ContextUniversalNativeRows.Result old=ContextUniversalNativeRows.inspect(x,positive,64,WORK);ContextUniversalFrozenConstraints.Result mixed=ContextUniversalFrozenConstraints.closeSignedInstantiatedUnits(old,p.frame.common,signedPool,null,16,16,512,256,WORK);require(!mixed.closed,"old row profile cannot silently consume explicit signed pool");
  ContextUniversalFrozenBranch.Limits l=limits(16,WORK);ContextSignedWitnessReceiver.Result good=ContextSignedWitnessReceiver.run(f,64,l,WORK);require(good.status==ContextSignedWitnessReceiver.Status.REFUTED,"qualified real contradiction control");reject(()->ContextSignedWitnessReceiver.check(good,f,64,l,1),"receiver receipt cannot reuse historical audit work");reject(()->ContextSignedWitnessReceiver.check(good,f,63,l,WORK),"receiver request rows bound exactly");reject(()->ContextSignedWitnessReceiver.check(good,p,64,l,WORK),"receiver request frame bound exactly");
  boolean oldRefused=false;try{ContextWitnessResultTransport.privatePoolSigned(f.frame.common,x,a,WORK);}catch(IllegalStateException expected){oldRefused=expected.getMessage().contains("Positive private witness bundle required");}require(oldRefused,"old positive-private API unchanged");
  System.out.println("SIGNED_WITNESS_RECEIVER_BOUNDARIES allRowsBeforeProof=true unsupportedBudgetAtomic=true modeAndScopeExact=true unsignedMixRejected=true oldPrivateApiUnchanged=true noAdmission=true");
 }
}
